    int h = (int)blockIdx.y * (int)blockDim.y + (int)threadIdx.y;
    int t = (int)blockIdx.x * 256 + (int)threadIdx.x;

    if (b >= B || h >= H || t >= L) return;

    int half = K / 2;
    int base = (b * H + h) * L;

