    dwconv1d_fwd_input_fused<<<grid, 256, shared_bytes>>>(
        (const float*)x, (const float*)k, (const float*)gy,
        y, gx, n, h, l, ks, use_shared);
    dwconv1d_bwd_kernel_naive<<<dim3((ks + 255) / 256, h, 1), 256>>>(
